airs",npc="Jorin Croge",k="giver"},["murlocs at the gates"]={c=S[48],x=2475.8,y=2048.2,w=S[458],q="Murlocs at the Gates",npc="Breton Samuels",k="giver"},["data rescue"]={c=S[48],x=-4824.6,y=-1265.4,w="Ironforge",q="Data Rescue",npc="Master Mechanic Castpipe",k="giver"},["mythology of the titans"]={c=S[48],x=-4635.7,y=-1303.4,w="Ironforge",q="Mythology of the Titans",npc="Librarian Mae Paledust",k="giver"},["oh brother..."]={c=S[48],x=-8241.4,y=590.1,w=S[322],q="Oh Brother...",npc=S[546],k="giver"},["open the maw"]={c=S[48],x=-3779.6,y=-2515.2,w="Wetlands",q="Open the Maw",npc="Deathstalker Agent",k="giver"},["power overwhelming"]={c=S[48],x=-8941,y=1069.6,w=S[322],q="Power Overwhelming",npc="High Sorcerer Andromath",k="giver"},["deviate hides"]={q="Deviate Hides",npc="Nalpak",k="dungeon",d=S[597],note="Nalpak stands in the alcove above the cavern entrance; the pin is the dungeon entrance."},["opportunistic education"]={q="Opportunistic Education",npc="Quest giver position unknown",k="dungeon",d="city of dalaran",note="The giver has no known map position, so the pin is the dungeon entrance."},["an unholy alliance"]={c=S[48],x=1286.5,y=334,w="Undercity",q="An Unholy Alliance",npc="Varimathras (turn-in)",k="giver",note="This quest starts from an item drop in Razorfen Downs; the pin is where you hand it in."}},specs={{id="discipline",name="Discipline",token="DISC",title="Discipline | WoW Forever Priest Field Guide",nav={{id="overview",x=S[552]},{id="journey",x=S[446]},{id="talents",x=S[392]},{id="stats",x=S[477]},{id="combat",x=S[478]},{id="macros",x=S[479]},{id="dungeons",x=S[420]},{id="professions",x=S[447]},{id="crafting",x=S[431]},{id="questgear",x=S[412]},{id=S[388],x=S[522]}},asideNote=S[72],talentString="52000503133001153130505000000000000005",ranks={{tree="Discipline",name=S[601],r=5,max=5},{tree="Discipline",name=S[402],r=2,max=2},{tree="Discipline",name=S[339],r=5,max=5},{tree="Discipline",name=S[470],r=3,max=3},{tree="Discipline",name="Inner Focus",r=1,max=1},{tree="Discipline",name=S[480],r=3,max=3},{tree="Discipline",name="Meditation",r=3,max=3},{tree="Discipline",name=S[612],r=1,max=1},{tree="Discipline",name="Penance",r=1,max=1},{tree="Discipline",name=S[576],r=5,max=5},{tree="Discipline",name=S[577],r=3,max=3},{tree="Discipline",name=S[537],r=1,max=1},{tree="Holy",name=S[471],r=3,max=3},{tree="Holy",name=S[403],r=5,max=5},{tree="Holy",name="Divine Fury",r=5,max=5},{tree="Shadow",name="Spirit Tap",r=5,max=5}},order={{l1=10,l2=11,tree="Discipline",name=S[402],r1=1,r2=2,max=2},{l1=12,l2=16,tree="Shadow",name="Spirit Tap",r1=1,r2=5,max=5},{l1=17,l2=19,tree="Holy",name=S[471],r1=1,r2=3,max=3},{l1=20,l2=24,tree="Discipline",name=S[601],r1=1,r2=5,max=5},{l1=25,l2=27,tree="Discipline",name=S[339],r1=1,r2=3,max=5},{l1=28,l2=30,tree="Discipline",name="Meditation",r1=1,r2=3,max=3},{l1=31,l2=32,tree="Discipline",name=S[339],r1=4,r2=5,max=5},{l1=33,l2=35,tree="Discipline",name=S[480],r1=1,r2=3,max=3},{l1=36,l2=36,tree="Discipline",name=S[612],r1=1,r2=1,max=1},{l1=37,l2=37,tree="Discipline",name=S[470],r1=1,r2=1,max=3},{l1=38,l2=38,tree="Discipline",name="Penance",r1=1,r2=1,max=1},{l1=39,l2=42,tree="Discipline",name=S[576],r1=1,r2=4,max=5},{l1=43,l2=43,tree="Discipline",name=S[577],r1=1,r2=1,max=3},{l1=44,l2=44,tree="Discipline",name=S[576],r1=5,r2=5,max=5},{l1=45,l2=46,tree="Discipline",name=S[577],r1=2,r2=3,max=3},{l1=47,l2=47,tree="Discipline",name=S[470],r1=2,r2=2,max=3},{l1=48,l2=48,tree="Discipline",name=S[537],r1=1,r2=1,max=1},{l1=49,l2=53,tree="Holy",name=S[403],r1=1,r2=5,max=5},{l1=54,l2=58,tree="Holy",name="Divine Fury",r1=1,r2=5,max=5},{l1=59,l2=59,tree="Discipline",name=S[470],r1=3,r2=3,max=3},{l1=60,l2=60,tree="Discipline",name="Inner Focus",r1=1,r2=1,max=1}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[413]},{t="p",s="legend",x=S[140],u=true},{t="h1",x="Discipline",sub=S[481]},{t="p",s="lede",x="Shield, heal and smite: Power Word: Shield buys time, Penance heals an ally or hits an enemy, and critical heals add Divine Aegis shields and shorten Weakened Soul through Renewed Hope."},{t="pills",list={S[519],"Dungeon healing and solo damage",S[448]}},{t="anchor",id="journey"},{t="kicker",x=S[553]},{t="h2",x=S[355]},{t="p",x="These stages follow the talent order below. Leveling as a healer is slower alone, but Discipline has the most damage of the two healing trees, and Penance works for both healing and damage."},{t="p",s="level",x=S[547]},{t="p",x="Shoot with a wand between Smite and Shadow Word: Pain casts; Power Word: Shield arrives at 6 and Renew at 8. Wand Specialization 2/2 at 11 adds 25% wand damage, Spirit Tap 5/5 by 16 doubles your Spirit after kills, and Twilight Focus 3/3 by 19 gives every spell a 70% chance to ignore pushback."},{t="p",s="level",x="20–39 · Power in Light and Penance"},{t="p",x="Holy Fire arrives at 20, so Power in Light 5/5 by 24 makes Smite and Penance hit 10% harder on targets with your Holy Fire or Shadow Word: Pain. Mental Strength and Meditation follow (50% of mana regeneration while casting by 30). Improved Power Word: Shield 3/3, Soul Warding at 36 (4 seconds shorter cooldown, 15% cheaper), Penance at 38 and Renewed Hope from 39."},{t="p",s="level",x="40–60 · Aegis and Power Infusion"},{t="p",x="Renewed Hope reaches 5/5 at 44, Divine Aegis 3/3 by 46 turns critical heals into shields, and Power Infusion at 48 gives a target 20% more spell damage and healing for 15 seconds. Holy Specialization 5/5 by 53 adds 5% Holy critical chance, Divine Fury 5/5 by 58 shortens Smite, Holy Fire, Heal and Greater Heal by 0.5 seconds, and Inner Focus completes the build at 60."},{t="anchor",id="talents"},{t="kicker",x=S[393]},{t="h2",x=S[519]},{t="p",x=S[60],u=true},{t="widget",w="talents"},{t="h4",s="summary",x=S[421]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[375]},{t="p",x=S[144]},{t="widget",w="order"},{t="p",s="notice",x="A group alternative: take Silent Resolve instead of Twilight Focus when you heal dungeons and pull threat. You can also respec at 35 to take Penance earlier, keeping Spirit Tap for mana. Divine Aegis shields absorb 15% of a non-periodic critical heal (capped by your level) for 12 seconds; Renewed Hope adds 10% critical chance on targets with Weakened Soul and shortens it by 5 seconds, so you can shield them again sooner."},{t="anchor",id="stats"},{t="kicker",x=S[482]},{t="h2",x=S[405]},{t="p",x="Discipline wants healing power first, then mana stats. Critical strike matters more here than for Holy because it triggers Divine Aegis and benefits from Renewed Hope."},{t="h3",x=S[538]},{t="stat",i=1,b=S[578],x=S[579]},{t="stat",i=2,b="Intellect",x=S[565]},{t="stat",i=3,b="Spirit",x=S[459]},{t="stat",i=4,b="Stamina",x=""},{t="stat",i=5,b=S[498],x=S[613]},{t="p",s="small",x="Wands with spell damage, Intellect and Spirit are good leveling picks."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[498],x=""},{t="stat",i=2,b="Mana per 5",x=""},{t="stat",i=3,b="Spirit",x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b=S[523],x=""},{t="p",s="small",x="Some estimates put Intellect second. Aim for a lot of all three of healing power, Intellect and Spirit, then refine by fight length."},{t="p",s="notice",x=S[75]},{t="anchor",id="combat"},{t="kicker",x=S[406]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Leave out what you have not learned yet: Holy Fire at 20, Penance at 38 and Power Infusion at 48 in this order."},{t="h4",x=S[466]},{t="p",x="Keep Power Word: Fortitude and Inner Fire up. Inner Fire has 20 charges, and each melee or ranged hit you take removes one; recast it when they run out. Shield yourself or the tank before the pull."},{t="h4",x="Solo damage"},{t="p",x="Holy Fire on the furthest or priority target, Smite as it approaches, Penance on the target with your Holy Fire, then Mind Blast and Shadow Word: Pain. Finish with your wand to save mana. Power in Light needs your Holy Fire or Shadow Word: Pain on the target."},{t="h4",x="Shield and Penance in groups"},{t="p",x="Shield whoever is about to take damage. Penance’s first heal is instant, so it is your fast response. Heals on a shielded target (Weakened Soul) crit more often through Renewed Hope, and critical heals leave Divine Aegis shields."},{t="h4",x="Heal, Renew and Flash Heal"},{t="p",x="Heal for steady damage, Renew for chip damage or while you move, Flash Heal only in emergencies because it costs much more mana. Prayer of Healing is for a party that is badly hurt."},{t="h4",x=S[580]},{t="p",x="Dispel Magic and Cure Disease (Abolish Disease from 32) only when the effect is worth the mana. Fade drops your threat when you pull enemies off the tank."},{t="h4",x="Cooldowns"},{t="p",x="Inner Focus makes the next spell free with 25% more critical chance; use it on an expensive heal. Power Infusion gives a caster or yourself 20% more damage and healing for 15 seconds."},{t="abil",names={S[581],"Penance","Smite","Holy Fire","Heal","Flash Heal","Renew",S[537],"Inner Focus"}},{t="h3",x=S[467]},{t="p",x="Priority for Discipline: healing power, mana per 5 seconds, Intellect, Spirit, then critical strike. Critical strike matters more here than for Holy because it triggers Divine Aegis and benefits from Renewed Hope."},{t="p",x="A strong wand is your main damage source until the mid-30s: Novice’s Practice Wand (1), Lesser Magic Wand (5) and Greater Magic Wand (13) from Enchanting, then Gravestone Scepter from Blackfathom Deeps. Priests start with one-handed maces and wands; learn Staves at a weapon master."},{t="h3",x=S[422]},{t="p",x="Mana is your limit. Carry water, use Spirit Tap and Meditation between pulls, and take it slow with a new group. When unsure, wand instead of casting damage spells so you never run out of mana for healing."},{t="p",x="Every Priest learns Fear Ward and Devouring Plague at 20 in Forever, and Divine Spirit at 30. Each race also has two Priest-only racial spells, such as Desperate Prayer and Chastise for Dwarves or Contingency Plan for Gnomes."},{t="anchor",id="macros"},{t="kicker",x=S[483]},{t="h2",x=S[340]},{t="p",x=S[52]},{t="p",s="notice",x=S[53]},{t="macro",n=S[389],x=S[86],code=S[146]},{t="macro",n=S[524],x=S[105],code=S[196]},{t="macro",n=S[460],x=S[117],code=S[171]},{t="macro",n=S[356],x=S[97],code=S[136]},{t="macro",n=S[433],x=S[113],code=S[162]},{t="macro",n=S[468],x=S[161],code=S[175]},{t="macro",n=S[348],x=S[152],code=S[390]},{t="macro",n=S[434],x=S[184],code=S[195]},{t="macro",n=S[461],x=S[192],code=S[289]},{t="macro",n="Penance heal, Shift for damage",x="Heals the ally under your pointer, your friendly target or yourself; hold Shift to hit your enemy target instead. A second press while it channels does not restart it.",code="#showtooltip Penance\n/stopmacro [channeling:Penance]\n/cast [mod:shift,harm,nodead][@mouseover,help,nodead][help,nodead][@player] Penance"},{t="macro",n="Mouseover Power Infusion",x="Gives the ally under your pointer, your friendly target or yourself 20% more spell damage and healing for 15 seconds.",code="#showtooltip Power Infusion\n/cast [@mouseover,help,nodead][help,nodead][@player] Power Infusion"},{t="macro",n="Mouseover Heal",x="Your steady, efficient heal from 16. Use a lower rank when the full rank would overheal.",code="#showtooltip Heal\n/cast [@mouseover,help,nodead][help,nodead][@player] Heal"},{t="macro",n="Mouseover Shadow Word: Pain",x="Applies Shadow Word: Pain to the enemy under your pointer or your target. Power in Light counts it as well as Holy Fire for bonus Smite and Penance damage.",code="#showtooltip Shadow Word: Pain\n/cast [@mouseover,harm,nodead][harm,nodead] Shadow Word: Pain"},{t="p",s="small",x=S[226]},{t="anchor",id="dungeons"},{t="kicker",x=S[525]},{t="h2",x=S[376]},{t="p",x=S[55]},{t="widget",w="rarity"},{t="p",s="notice",x=S[56]},{t="p",s="notice",x=S[29]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[407]},{t="h2",x=S[373]},{t="p",x=S[66]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[423]},{t="h2",x=S[357]},{t="p",x=S[25]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[408]},{t="h2",x=S[332]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[388]},{t="kicker",x=S[526]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[87]}}},{id="holy",name="Holy",token="HOLY",title="Holy | WoW Forever Priest Field Guide",nav={{id="overview",x=S[552]},{id="journey",x=S[446]},{id="talents",x=S[392]},{id="stats",x=S[477]},{id="combat",x=S[478]},{id="macros",x=S[479]},{id="dungeons",x=S[420]},{id="professions",x=S[447]},{id="crafting",x=S[431]},{id="questgear",x=S[412]},{id=S[388],x=S[522]}},asideNote=S[72],talentString="02300500103000000033205101032021531005",ranks={{tree="Discipline",name=S[402],r=2,max=2},{tree="Discipline",name=S[442],r=3,max=5},{tree="Discipline",name=S[339],r=5,max=5},{tree="Discipline",name="Inner Focus",r=1,max=1},{tree="Discipline",name="Meditation",r=3,max=3},{tree="Holy",name=S[471],r=3,max=3},{tree="Holy",name=S[602],r=3,max=3},{tree="Holy",name=S[403],r=2,max=5},{tree="Holy",name="Divine Fury",r=5,max=5},{tree="Holy",name="Holy Nova",r=1,max=1},{tree="Holy",name="Inspiration",r=1,max=3},{tree="Holy",name=S[591],r=3,max=3},{tree="Holy",name=S[609],r=2,max=2},{tree="Holy",name=S[598],r=2,max=2},{tree="Holy",name=S[548],r=1,max=1},{tree="Holy",name=S[414],r=5,max=5},{tree="Holy",name=S[588],r=3,max=3},{tree="Holy",name=S[505],r=1,max=1},{tree="Shadow",name="Spirit Tap",r=5,max=5}},order={{l1=10,l2=11,tree="Discipline",name=S[402],r1=1,r2=2,max=2},{l1=12,l2=16,tree="Shadow",name="Spirit Tap",r1=1,r2=5,max=5},{l1=17,l2=19,tree="Holy",name=S[471],r1=1,r2=3,max=3},{l1=20,l2=22,tree="Holy",name=S[602],r1=1,r2=3,max=3},{l1=23,l2=25,tree="Discipline",name=S[442],r1=1,r2=3,max=5},{l1=26,l2=30,tree="Discipline",name=S[339],r1=1,r2=5,max=5},{l1=31,l2=33,tree="Discipline",name="Meditation",r1=1,r2=3,max=3},{l1=34,l2=37,tree="Holy",name="Divine Fury",r1=1,r2=4,max=5},{l1=38,l2=38,tree="Holy",name="Holy Nova",r1=1,r2=1,max=1},{l1=39,l2=39,tree="Holy",name="Inspiration",r1=1,r2=1,max=3},{l1=40,l2=40,tree="Holy",name="Divine Fury",r1=5,r2=5,max=5},{l1=41,l2=42,tree="Holy",name=S[403],r1=1,r2=2,max=5},{l1=43,l2=44,tree="Holy",name=S[609],r1=1,r2=2,max=2},{l1=45,l2=47,tree="Holy",name=S[591],r1=1,r2=3,max=3},{l1=48,l2=48,tree="Holy",name=S[548],r1=1,r2=1,max=1},{l1=49,l2=50,tree="Holy",name=S[598],r1=1,r2=2,max=2},{l1=51,l2=52,tree="Holy",name=S[414],r1=1,r2=2,max=5},{l1=53,l2=55,tree="Holy",name=S[588],r1=1,r2=3,max=3},{l1=56,l2=57,tree="Holy",name=S[414],r1=3,r2=4,max=5},{l1=58,l2=58,tree="Holy",name=S[505],r1=1,r2=1,max=1},{l1=59,l2=59,tree="Holy",name=S[414],r1=5,r2=5,max=5},{l1=60,l2=60,tree="Discipline",name="Inner Focus",r1=1,r2=1,max=1}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[413]},{t="p",s="legend",x=S[140],u=true},{t="h1",x="Holy",sub=S[481]},{t="p",s="lede",x="Reactive group healing: Renew, Heal and Flash Heal for the tank, Prayer of Mending bouncing through the party, Litany of Light refunding mana, and Holy Nova when Searing Light makes it free."},{t="pills",list={S[520],"Dungeon and group healing",S[448]}},{t="anchor",id="journey"},{t="kicker",x=S[553]},{t="h2",x=S[355]},{t="p",x="These stages follow the talent order below. Holy is the easier healing tree to pick up; it levels best in groups, and Holy Nova gives it the only area damage a Priest has."},{t="p",s="level",x=S[547]},{t="p",x="Shoot with a wand between spells; Power Word: Shield arrives at 6 and Renew at 8. Wand Specialization 2/2 at 11, Spirit Tap 5/5 by 16 and Twilight Focus 3/3 by 19 make solo questing smoother and protect your casts from pushback."},{t="p",s="level",x="20–39 · Renew and efficiency"},{t="p",x="Improved Renew 3/3 by 22 adds 15% to Renew, Twin Disciplines 3/5 by 25 adds 3% to instant spells, Mental Strength 5/5 by 30 adds 10% Intellect, and Meditation 3/3 by 33 lets half of your mana regeneration continue while casting. Divine Fury follows, with Holy Nova at 38 and Inspiration at 39."},{t="p",s="level",x="40–60 · Spirit and Mending"},{t="p",x="Divine Fury reaches 5/5 at 40 (with Greater Heal), then Holy Specialization, Searing Light (free Holy Nova procs from Holy Fire), Improved Healing (15% cheaper heals), Spirit of Redemption at 48 and Litany of Light 2/2 by 50. Spiritual Guidance and Spiritual Healing fill 51–59, Prayer of Mending arrives at 58 and Inner Focus completes the build at 60."},{t="anchor",id="talents"},{t="kicker",x=S[393]},{t="h2",x=S[520]},{t="p",x=S[60],u=true},{t="widget",w="talents"},{t="h4",s="summary",x=S[421]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[375]},{t="p",x=S[144]},{t="widget",w="order"},{t="p",s="notice",x="Holy Binding (Flash Heal heals you for 50% as much) is an option if you take damage while healing; this build does not take it. Litany of Light refunds 10% of a heal’s base mana cost when your previous heal was a different spell, and Spiritual Guidance turns 25% of your Spirit into healing power."},{t="anchor",id="stats"},{t="kicker",x=S[482]},{t="h2",x=S[405]},{t="p",x="Holy wants healing power first, then the mana stats that keep you casting. Spiritual Guidance turns Spirit into extra healing."},{t="h3",x=S[538]},{t="stat",i=1,b=S[578],x=S[579]},{t="stat",i=2,b="Intellect",x=S[565]},{t="stat",i=3,b="Spirit",x="also adds healing with Spiritual Guidance"},{t="stat",i=4,b="Stamina",x=""},{t="stat",i=5,b=S[498],x=S[613]},{t="p",s="small",x="Holy levels best in groups; keep a healing set for dungeons."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[498],x=""},{t="stat",i=2,b="Mana per 5",x=""},{t="stat",i=3,b="Spirit",x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b=S[523],x=""},{t="p",s="small",x="Critical strike is last because a crit often overheals. Some estimates put Intellect second."},{t="p",s="notice",x=S[75]},{t="anchor",id="combat"},{t="kicker",x=S[406]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Heal arrives at 16, Flash Heal at 20, Holy Nova at 38, Greater Heal at 40 and Prayer of Mending at 58 in this order."},{t="h4",x=S[466]},{t="p",x="Keep Power Word: Fortitude and Inner Fire up, and Divine Spirit from 30. Shield yourself or the tank before the pull."},{t="h4",x="Solo damage"},{t="p",x="Holy Fire on the furthest or priority target, Smite as it approaches, then Mind Blast and Shadow Word: Pain, and finish with your wand. Against several enemies, use Holy Nova when Searing Light makes it free."},{t="h4",x="Renew and Prayer of Mending"},{t="p",x="Keep Renew on the tank while they take steady damage; several Priests’ Renews can share a target in Forever. Place Prayer of Mending on whoever is about to take damage so it heals and jumps through the group."},{t="h4",x="Heal and Greater Heal"},{t="p",x="Heal (Greater Heal from 40) for moderate healing after a few seconds. Use lower ranks so you do not overheal; alternating different heals triggers Litany of Light refunds."},{t="h4",x="Emergencies"},{t="p",x="Power Word: Shield buys time, Flash Heal is the fast but expensive answer, and Prayer of Healing heals the whole party when everyone is hurt. Inner Focus makes one big heal free."},{t="h4",x=S[580]},{t="p",x="Dispel Magic and Cure Disease (Abolish Disease from 32) when the effect is worth removing. Fade if enemies turn to you."},{t="abil",names={"Renew","Heal","Greater Heal","Flash Heal",S[505],"Prayer of Healing","Holy Nova",S[581],"Inner Focus"}},{t="h3",x=S[467]},{t="p",x="Priority for Holy: healing power, mana per 5 seconds, Spirit (Spiritual Guidance turns it into healing), Intellect, and critical strike last, since a crit often just overheals."},{t="p",x="A strong wand is your main damage source until the mid-30s: Novice’s Practice Wand (1), Lesser Magic Wand (5) and Greater Magic Wand (13) from Enchanting, then Gravestone Scepter from Blackfathom Deeps. Learn Staves at a weapon master before your first staff."},{t="h3",x=S[422]},{t="p",x="Heal with lower ranks to avoid overhealing, alternate different heals for Litany of Light, and let Renew finish before refreshing it. Keep enough mana for an emergency Flash Heal."},{t="p",x="Spirit of Redemption keeps you healing for 15 seconds after death. Every Priest learns Fear Ward and Devouring Plague at 20 and Divine Spirit at 30 in Forever."},{t="anchor",id="macros"},{t="kicker",x=S[483]},{t="h2",x=S[340]},{t="p",x=S[52]},{t="p",s="notice",x=S[53]},{t="macro",n=S[389],x=S[86],code=S[146]},{t="macro",n=S[524],x=S[105],code=S[196]},{t="macro",n=S[460],x=S[117],code=S[171]},{t="macro",n=S[356],x=S[97],code=S[136]},{t="macro",n=S[433],x=S[113],code=S[162]},{t="macro",n=S[468],x=S[161],code=S[175]},{t="macro",n=S[348],x=S[152],code=S[390]},{t="macro",n=S[434],x=S[184],code=S[195]},{t="macro",n=S[461],x=S[192],code=S[289]},{t="macro",n="Mouseover Prayer of Mending",x="Places Prayer of Mending on the ally under your pointer, your friendly target or yourself. Put it on someone about to take damage.",code="#showtooltip Prayer of Mending\n/cast [@mouseover,help,nodead][help,nodead][@player] Prayer of Mending"},{t="macro",n="Greater Heal, Shift for Rank 1",x="Normal press casts your highest Greater Heal; Shift casts Rank 1 for a smaller, cheaper heal. Learned at 40.",code="#showtooltip Greater Heal\n/cast [mod:shift,@mouseover,help,nodead][mod:shift,help,nodead][mod:shift,@player] Greater Heal(Rank 1); [@mouseover,help,nodead][help,nodead][@player] Greater Heal"},{t="macro",n="Inner Focus and Greater Heal",x="Makes the next Greater Heal free with 25% more critical chance, on the ally under your pointer, your friendly target or yourself.",code="#showtooltip Inner Focus\n/cast Inner Focus\n/cast [@mouseover,help,nodead][help,nodead][@player] Greater Heal"},{t="macro",n="Holy Nova",x="Damages enemies and heals party members within 10 yards. Best when Searing Light makes it free.",code="#showtooltip Holy Nova\n/cast Holy Nova"},{t="p",s="small",x=S[226]},{t="anchor",id="dungeons"},{t="kicker",x=S[525]},{t="h2",x=S[376]},{t="p",x=S[55]},{t="widget",w="rarity"},{t="p",s="notice",x=S[56]},{t="p",s="notice",x=S[29]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[407]},{t="h2",x=S[373]},{t="p",x=S[66]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[423]},{t="h2",x=S[357]},{t="p",x=S[25]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[408]},{t="h2",x=S[332]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[388]},{t="kicker",x=S[526]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[87]}}},{id="shadow",name="Shadow",token="SHADOW",title="Shadow | WoW Forever Priest Field Guide",nav={{id="overview",x=S[552]},{id="journey",x=S[446]},{id="talents",x=S[392]},{id="stats",x=S[477]},{id="combat",x=S[478]},{id="macros",x=S[479]},{id="dungeons",x=S[420]},{id="professions",x=S[447]},{id="crafting",x=S[431]},{id="questgear",x=S[412]},{id=S[388],x=S[522]}},asideNote=S[72],talentString="0050032010300000000000000000000000055502201221312051",ranks={{tree="Discipline",name=S[442],r=5,max=5},{tree="Discipline",name=S[339],r=3,max=5},{tree="Discipline",name="Martyrdom",r=2,max=2},{tree="Discipline",name="Inner Focus",r=1,max=1},{tree="Discipline",name="Meditation",r=3,max=3},{tree="Shadow",name=S[582],r=5,max=5},{tree="Shadow",name="Blackout",r=5,max=5},{tree="Shadow",name="Spirit Tap",r=5,max=5},{tree="Shadow",name=S[499],r=2,max=2},{tree="Shadow",name=S[614],r=2,max=2},{tree="Shadow",name="Mind Flay",r=1,max=1},{tree="Shadow",name=S[583],r=2,max=2},{tree="Shadow",name=S[592],r=2,max=5},{tree="Shadow",name=S[515],r=1,max=1},{tree="Shadow",name=S[603],r=3,max=3},{tree="Shadow",name="Silence",r=1,max=1},{tree="Shadow",name=S[566],r=2,max=2},{tree="Shadow",name="Darkness",r=5,max=5},{tree="Shadow",name="Shadowform",r=1,max=1}},order={{l1=10,l2=14,tree="Shadow",name="Spirit Tap",r1=1,r2=5,max=5},{l1=15,l2=16,tree="Shadow",name=S[499],r1=1,r2=2,max=2},{l1=17,l2=18,tree="Shadow",name=S[614],r1=1,r2=2,max=2},{l1=19,l2=19,tree="Shadow",name=S[582],r1=1,r2=1,max=5},{l1=20,l2=24,tree="Shadow",name="Blackout",r1=1,r2=5,max=5},{l1=25,l2=25,tree="Shadow",name=S[515],r1=1,r2=1,max=1},{l1=26,l2=28,tree="Shadow",name=S[603],r1=1,r2=3,max=3},{l1=29,l2=29,tree="Shadow",name="Mind Flay",r1=1,r2=1,max=1},{l1=30,l2=30,tree="Shadow",name="Silence",r1=1,r2=1,max=1},{l1=31,l2=32,tree="Shadow",name=S[566],r1=1,r2=2,max=2},{l1=33,l2=34,tree="Shadow",name=S[583],r1=1,r2=2,max=2},{l1=35,l2=39,tree="Shadow",name="Darkness",r1=1,r2=5,max=5},{l1=40,l2=40,tree="Shadow",name="Shadowform",r1=1,r2=1,max=1},{l1=41,l2=45,tree="Discipline",name=S[442],r1=1,r2=5,max=5},{l1=46,l2=47,tree="Discipline",name="Martyrdom",r1=1,r2=2,max=2},{l1=48,l2=50,tree="Discipline",name=S[339],r1=1,r2=3,max=5},{l1=51,l2=53,tree="Discipline",name="Meditation",r1=1,r2=3,max=3},{l1=54,l2=54,tree="Discipline",name="Inner Focus",r1=1,r2=1,max=1},{l1=55,l2=58,tree="Shadow",name=S[582],r1=2,r2=5,max=5},{l1=59,l2=60,tree="Shadow",name=S[592],r1=1,r2=2,max=5}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[413]},{t="p",s="legend",x=S[140],u=true},{t="h1",x="Shadow",sub=S[481]},{t="p",s="lede",x="Damage over time from range: Shadow Word: Pain, Devouring Plague and Mind Blast, Mind Flay between them, and Shadowform at 40 to halve your Shadow mana costs."},{t="pills",list={S[521],"Solo questing and ranged damage",S[448]}},{t="anchor",id="journey"},{t="kicker",x=S[553]},{t="h2",x=S[355]},{t="p",x="These stages follow the talent order below. Shadow has the least downtime for solo questing; mana is tight until Shadowform at 40."},{t="p",s="level",x="10–24 · Spirit Tap and reach"},{t="p",x="Spirit Tap 5/5 at 14 doubles your Spirit after a kill and lets 50% of your mana regeneration continue while casting. Improved Shadow Word: Pain adds 6 seconds to the damage-over-time spell, Shadow Reach adds 20% range to your Shadow spells, and Blackout 5/5 by 24 gives Shadow damage a 10% chance to stun."},{t="p",s="level",x="25–39 · Embrace, Flay and Contagion"},{t="p",x="Vampiric Embrace at 25 heals your party for 20% of your Shadow damage, Shadow Weaving 3/3 by 28 stacks up to 10% more Shadow damage from you, Mind Flay at 29 replaces Smite as your filler, and Silence at 30 is your interrupt. Devouring Contagion 2/2 (31–32) halves Devouring Plague’s cost and spreads it on death, Improved Mind Flay 2/2 (33–34) ramps each tick, and Darkness 5/5 by 39 adds 10% Shadow damage."},{t="p",s="level",x="40–60 · Shadowform and support"},{t="p",x="Shadowform at 40: 10% more Shadow damage, half-cost Shadow spells, double the critical damage bonus and 15% less physical damage taken, but no healing spells while it is active. Twin Disciplines, Martyrdom, Mental Strength, Meditation and Inner Focus fill 41–54, Shadow Focus reaches 5/5 at 58 for 5% Shadow hit, and Dark Inspiration finishes the build at 60."},{t="anchor",id="talents"},{t="kicker",x=S[393]},{t="h2",x=S[521]},{t="p",x=S[60],u=true},{t="widget",w="talents"},{t="h4",s="summary",x=S[421]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[375]},{t="p",x="Spend one point per level in each range. Unlisted talents stay at zero. This order runs to 60 and has been checked for totals, maximum ranks, tier gates and prerequisites."},{t="widget",w="order"},{t="p",s="notice",x="The build takes Blackout for its stuns; take Shadow Focus instead if you miss many casts in dungeons or on higher-level enemies. Another option is a wand-based Discipline build for 10–39 (Meditation first) with a respec at 40; this page follows the Shadow build from 10. Shadow Weaving in Forever only boosts your own Shadow damage."},{t="anchor",id="stats"},{t="kicker",x=S[482]},{t="h2",x=S[405]},{t="p",x="Shadow wants hit until the cap, then spell power and critical strike. Mana is tight until Shadowform, so Spirit helps while you level."},{t="h3",x=S[538]},{t="stat",i=1,b=S[578],x=S[516]},{t="stat",i=2,b="Spirit",x=S[459]},{t="stat",i=3,b="Intellect",x="mana pool"},{t="stat",i=4,b="Stamina",x=""},{t="p",s="small",x="From level 36, pick wands with spell damage, Intellect and Spirit."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[516]},{t="stat",i=3,b=S[523],x=""},{t="stat",i=4,b="Spell penetration",x=""},{t="stat",i=5,b="Spirit",x=""},{t="p",s="small",x="Shadow Focus gives 5% hit, so you need 12% from gear. Some estimates put crit above spell power."},{t="p",s="notice",x="Spell hit cap: 17% against raid bosses (level 63), 4% against enemies of your own level. The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[406]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Mind Flay arrives at 29 in this order, Shadow Word: Death at 32 and Shadowform at 40."},{t="h4",x=S[466]},{t="p",x="Keep Power Word: Fortitude and Inner Fire up. From 40, enter Shadowform before the pull and stay in it; leave it only to heal yourself."},{t="h4",x="Open"},{t="p",x="Shield yourself if the enemy will reach you (skip it in groups), then pull with Mind Blast. Before Mind Flay, open with Smite and follow with Mind Blast."},{t="h4",x="Apply damage over time"},{t="p",x="Shadow Word: Pain, then Devouring Plague (every Priest learns it at 20). With Devouring Contagion, the Plague spreads to two nearby enemies when the target dies."},{t="h4",x="Mind Flay and wand"},{t="p",x="Channel Mind Flay between spells and let it finish when safe: Improved Mind Flay makes each tick stronger than the last. Before 36 or when low on mana, finish with your wand instead."},{t="h4",x="Finish"},{t="p",x="From 32, Shadow Word: Death finishes an enemy it will kill; if the target survives, you take damage equal to 30% of your maximum health."},{t="h4",x="Control and recovery"},{t="p",x="Silence interrupts dangerous casts, Psychic Scream (14) buys room but can pull more enemies, and Vampiric Embrace heals you and your party. Spirit Tap and Dark Inspiration speed up mana recovery after kills."},{t="abil",names={"Shadowform","Mind Blast","Shadow Word: Pain","Devouring Plague","Mind Flay","Shadow Word: Death",S[515],"Silence"}},{t="h3",x=S[467]},{t="p",x="Leveling priority for Shadow: spell damage, critical strike, hit, then Intellect, Stamina and mana per 5 seconds. Hit becomes more important at 60 and against higher-level enemies."},{t="p",x="Use wands until Mind Flay takes over in your mid-30s; wand shots do not scale with spell damage. Gravestone Scepter (Blackfathom Deeps) adds Shadow damage and Spirit, which keep it useful after you stop shooting."},{t="h3",x=S[422]},{t="p",x="You do not need a healing spec to heal leveling dungeons: leave Shadowform and heal with Renew, Power Word: Shield and downranked Heal. After 40 healing gets harder, so consider a second healing spec at 50–60."},{t="p",x="In groups, Vampiric Embrace keeps the party topped up and Dark Inspiration raises their Spirit. Pulling several enemies with Shadow Word: Pain is possible but drains Inner Fire charges and mana quickly."},{t="anchor",id="macros"},{t="kicker",x=S[483]},{t="h2",x=S[340]},{t="p",x=S[52]},{t="p",s="notice",x=S[53]},{t="macro",n=S[389],x=S[86],code=S[146]},{t="macro",n=S[524],x=S[105],code=S[196]},{t="macro",n=S[460],x=S[117],code=S[171]},{t="macro",n=S[356],x=S[97],code=S[136]},{t="macro",n=S[433],x=S[113],code=S[162]},{t="macro",n=S[468],x=S[161],code=S[175]},{t="macro",n=S[348],x=S[152],code=S[390]},{t="macro",n=S[434],x=S[184],code=S[195]},{t="macro",n=S[461],x=S[192],code=S[289]},{t="macro",n="Mouseover Silence",x="Stops your current cast and silences the enemy under your pointer or your target, interrupting its spell.",code="#showtooltip Silence\n/stopcasting\n/cast [@mouseover,harm,nodead][harm,nodead] Silence"},{t="macro",n="Mind Flay without restarting",x="Repeated presses do not restart the channel, so you keep the stronger later ticks from Improved Mind Flay.",code="#showtooltip Mind Flay\n/cast [nochanneling:Mind Flay] Mind Flay"},{t="macro",n="Shadow Word: Death finisher",x="Use only when it will kill the target; if it survives, you take damage equal to 30% of your maximum health.",code="#showtooltip Shadow Word: Death\n/cast [harm,nodead] Shadow Word: Death"},{t="macro",n="Leave Shadowform and heal",x="Cancels Shadowform, then Flash Heals the ally under your pointer or yourself. Recast Shadowform after the fight. Not tested in game.",code="#showtooltip Flash Heal\n/cancelaura Shadowform\n/cast [@mouseover,help,nodead][@player] Flash Heal"},{t="p",s="small",x=S[226]},{t="anchor",id="dungeons"},{t="kicker",x=S[525]},{t="h2",x=S[376]},{t="p",x=S[55]},{t="widget",w="rarity"},{t="p",s="notice",x=S[56]},{t="p",s="notice",x=S[29]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[407]},{t="h2",x=S[373]},{t="p",x=S[66]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[423]},{t="h2",x=S[357]},{t="p",x=S[25]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[408]},{t="h2",x=S[332]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[388]},{t="kicker",x=S[526]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[87]}}}},dungeons={{n=S[321],lr="13–18",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={},t={},no={S[39],S[167],S[31]}}},{n=S[285],lr="13–18",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={},t={},no={S[39],S[167],S[31]}}},{n=S[165],lr="15–20",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={{n="Lordaeron Captain",st=S[80],no=S[95],it={}}},t={},no={S[91],S[41],S[31]}}},{n=S[212],lr="17–24",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={{n=S[444],st=S[80],no=S[95],it={}}},t={},no={S[91],S[167],S[31]}}},{n=S[214],lr="17–26",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={{n="Miner Johnson",st=S[80],no=S[245],it={}}},t={},no={S[91],S[41],S[31]}}},{n=S[228],lr="22–30",st=S[123],no=S[16],ba=true,ra={ck=S[166],r={{n="Deathsworn Captain",st=S[80],no=S[95],it={}},{